package com.example.jobfinderapp.models;
public class Project { private int id,userId; private String projectName,role,description,technologies,startDate,endDate,githubUrl,demoUrl; public int getId(){return id;}public void setId(int v){id=v;}public int getUserId(){return userId;}public void setUserId(int v){userId=v;}public String getProjectName(){return projectName;}public void setProjectName(String v){projectName=v;}public String getRole(){return role;}public void setRole(String v){role=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getTechnologies(){return technologies;}public void setTechnologies(String v){technologies=v;}public String getStartDate(){return startDate;}public void setStartDate(String v){startDate=v;}public String getEndDate(){return endDate;}public void setEndDate(String v){endDate=v;}public String getGithubUrl(){return githubUrl;}public void setGithubUrl(String v){githubUrl=v;}public String getDemoUrl(){return demoUrl;}public void setDemoUrl(String v){demoUrl=v;} }
